import{readFileSync}from'node:fs';
import{pairedStats,classifyRatio,median}from'/var/folders/0r/pkz80d0154z37ybnv69pqclh0000gn/T/bend-build-acceleration-3cg3qjns/g73-real-leaf-frames-3fvdekrb/repository/evals/selfhost_corpus_calibration.ts';
