const comparison:any={};for(const metric of['checkerCpuMs','checkerWallMs','footprintBytes','rssBytes']){const statistics=pairedStats(pairs.map((p:any)=>p.A[metric]),pairs.map((p:any)=>p.C[metric]));comparison[metric]={...statistics,direction:classifyRatio(statistics.ci95,.02)};}
comparison.medianFootprintRatio=median(pairs.map((p:any)=>p.C.footprintBytes))!/median(pairs.map((p:any)=>p.A.footprintBytes))!;
comparison.medianRSSRatio=median(pairs.map((p:any)=>p.C.rssBytes))!/median(pairs.map((p:any)=>p.A.rssBytes))!;
const pointScreen={cpu:comparison.checkerCpuMs.geometricMeanRatio<=limit.geometricCPU_CA_atMost,everyCPU:pairs.every((p:any)=>p.C.checkerCpuMs/p.A.checkerCpuMs<limit.everyCPU_CA_below),wall:comparison.checkerWallMs.geometricMeanRatio<=limit.geometricWall_CA_atMost,medianFootprint:comparison.medianFootprintRatio<=limit.medianPhysicalFootprint_CA_atMost};
